// Spatial immersion index — record JAH-GPC-SPATIALAUDIO-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"anc_db": 30, "battery_h": 40, "price_usd": 380};
var value = (m.anc_db*m.battery_h/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPC-SPATIALAUDIO-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPC-SPATIALAUDIO-000001|' + value.toFixed(2) + ' immersion index');

